SELECT id,symbol,JSON_UNQUOTE(JSON_EXTRACT(snapshot_json,'$.research.name')) AS name,horizon,action_code,archived,created_at,
CAST(JSON_UNQUOTE(JSON_EXTRACT(snapshot_json,'$.research.asOf')) AS DATE) AS as_of, NULL AS latest_review_date, NULL AS latest_review_status, NULL AS latest_review_explanation
FROM research_plan  ORDER BY id DESC LIMIT #{size} OFFSET #{offset}
